var ULID_CHARS = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
function encodeTime(now, len){
  var str = "";
  for (var i = len - 1; i >= 0; i--){ var mod = now % 32; str = ULID_CHARS[mod] + str; now = Math.floor(now / 32); }
  return str;
}
function ulid(now, rnd){
  if (now == null) now = Date.now();
  if (rnd == null) rnd = Math.random;
  return encodeTime(now, 10) + encodeRandom(16, rnd);
}
function encodeRandom(len, rnd){
  var str = "";
  for (var i = 0; i < len; i++) str += ULID_CHARS[Math.floor(rnd() * 32)];
  return str;
}
function decodeTime(id){
  var t = 0;
  for (var i = 0; i < 10; i++){ var idx = ULID_CHARS.indexOf(id.charAt(i)); if (idx < 0) return NaN; t = t * 32 + idx; }
  return t;
}
var EXPORTS = { ULID_CHARS: ULID_CHARS, ulid: ulid, decodeTime: decodeTime };

